# Own-wording items of Dark Matter (2014 rules). Texts follow the 2014 source numbers. REUSE lists items whose 2024 text is identical in rules.
ITEMS = []; SP = {}; WPN = {}; GEAR = []
REUSE = set("""Ankh of Ra|Arm Blade|Bandolier|Binoculars|Comm Set|Concentration Module|Cryogenic Pod|Embedded Translator|Encyclopedia Multiplanaria|Engineer's Pack|Etheradio|Flare|Flashlight|Gravity Nullifier|Heavy Legs|Holo-Companion|Holster|Hypodermic Needle|Igniter|Infrasight Eyes|Interface Rig|Jetpack|Life Suit|Log Keeper|Logic Unit|Omnitool|Potion of Solar Radiance|Quadcorder|Replacement|Researcher's Pack|Ring of Paradoxes|Roach|Shield Module|Skeleton Keycard|Sling|Spider Pod|Tactical Vest|Terraforming Engine|Traction Spikes|Universal Translator|Vent Tape|Void Beacon|Weapon Wheel|Wristwatch""".split("|"))
def add(name, typ, rar, att, text, **o):
    ITEMS.append((name, typ, rar, att, text, o))
def gear(name, gp, wt, cat, text):
    GEAR.append([name, gp, wt, cat, text])

add("Adamantine Plating", "Wondrous Item", "Uncommon", 0, "Graft (External slot, 2,250 gp). Vect only. Your Armor Class is 17 and a critical hit against you becomes a normal hit. You cannot wear conventional armor with it. You can install it only if you are proficient with heavy armor.")
add("Arcane Synapses", "Wondrous Item", "Uncommon", 0, "Graft (Head slot, 325 gp). Extra arcane nerves in your brain teach you one wizard cantrip of your choice. Intelligence is its spellcasting ability.")
add("Embedded Battlefist", "Wondrous Item", "Uncommon", 0, "Graft (Arms slot, 200 gp). One hand (your choice) is replaced by a battlefist. You are proficient with it and cannot be disarmed of it. It has the Light property.")
add("Embedded Phaser", "Wondrous Item", "Uncommon", 0, "Graft (Arms slot, 250 gp). A mechanical hand can turn into a phaser whenever you could draw a weapon, and back when you could stow one. You are proficient with it and cannot be disarmed of it. A transformed arm cannot hold or use anything else.")
add("Finger Picks", "Wondrous Item", "Uncommon", 0, "Graft (Arms slot, 800 gp). Thieves' Tools are built into the fingers of a mechanical hand. You always have them on you and can hide them perfectly. If you are proficient with Thieves' Tools, you add +2 to ability checks made with them.")
add("Mithral Plating", "Wondrous Item", "Rare", 0, "Graft (External slot, 1,500 gp). Your Armor Class is 14 + Dexterity modifier and you have Resistance to Lightning damage. You can install it only if you are proficient with light armor.")
add("Spiked Plating", "Wondrous Item", "Uncommon", 0, "Graft (External slot, 750 gp). Your Armor Class is 14 + Dexterity modifier (max +2). Your unarmed strikes deal 1d4 Piercing damage, and a creature you are grappling at the start of your turn takes 1d4 Piercing damage. You can install it only if you are proficient with medium armor.")
add("Tesla Module", "Wondrous Item", "Uncommon", 0, "Graft (Internal slot, 350 gp). A chest unit charges your skin. When a creature within 5 ft hits you with an attack, use your reaction to deal 1d6 Lightning damage to each creature within 5 ft of you.")
add("Thermoregulator", "Wondrous Item", "Uncommon", 0, "Graft (Internal slot, 500 gp). You endure the Extreme Temperatures of space and other harsh places without taking damage.")
add("Wings", "Wondrous Item", "Rare", 0, "Graft (External slot, 5,500 gp). Silver clockwork wings fold into a hump on your back. Deploy or retract them as a bonus action. Deployed, you have a flying speed equal to your walking speed, for 10 minutes total until you finish a short or long rest. As a reaction while falling you can deploy them to glide down safely, even with no flight time left.")
add("Overdrive Module", "Wondrous Item", "Rare", 0, "Graft (Internal slot). As a bonus action you start an internal generator for up to 1 minute. During that time a 19 on an ability check, attack roll or saving throw counts as a 20. It ends early if you roll a 1. Short or Long Rest to use again.", ch=[1, "1", "short"])
add("Final Word", "Wondrous Item", "Legendary", 0, "Graft (Internal slot, tied to your life). An arcane warhead inside you detonates when you die. It destroys your body, so only true resurrection or wish can restore you. Each creature within 180 ft makes a DC 18 Dexterity save, taking 1d4 mega Force damage on a failure or half on a success. Creatures within 60 ft with Evasion or similar cannot avoid this damage.")
add("Impulse Unit", "Wondrous Item", "Uncommon", 0, "Graft (Legs slot). Thrusters in your legs and back let you spend 10 ft of movement to leap 10 ft straight up on your turn. In zero gravity you can move 20 ft in any direction on your turn.")
add("Heart of Steel", "Wondrous Item", "Uncommon", 0, "Graft (Internal slot). A construct core replaces your heart. You ignore the effects of 1 level of exhaustion and need only 4 hours of rest to gain the benefit of 8 hours of sleep. Vect cannot install it.")
add("Arm Cannon", "Weapon", "Uncommon", 0, "Graft (Arms slot). An arm is replaced by a blaster cannon, 2d8 Radiant, Blaster property, range 30/120 ft. You are proficient with it and cannot be disarmed of it. It has no hand, so that arm cannot hold or use other objects. Only one arm can be an arm cannon.", base=["Repeater"])
add("Death Ray", "Weapon", "Very Rare", 1, "A blaster (2d6 Radiant, range 60/240, Blaster). You have a +2 bonus to attack and damage rolls with it. It has 2 charges and regains 1d2 at dawn. While attuned, spend 1 charge to cast Disintegrate (DC 16) at a target you see within range.", ch=[2, "1d2", "dawn"], base=["Repeater"], fx={"atk": 2, "dmg": 2})
add("BEG-3000", "Weapon", "Legendary", 1, "An experimental singularity emitter (2d10 Force, range 120/480, Blaster, Heavy, Overheat, Special, Two-Handed). You have a +3 bonus to attack and damage rolls with it. It has 4 charges and regains 1d4 at dawn. As an action, spend a charge to fire an unstable singularity to a point you see within 60 ft. Roll a d20. On a 5 or lower it spends all remaining charges instead of one. Each creature in a 20-ft-radius sphere there makes a DC 17 Dexterity save, taking 10d10 Force damage on a failure or half on a success. The weapon then overheats and cannot spend a charge or attack until the end of your next turn. Special: when it hits, each creature within 10 ft of the target is pulled up to 5 ft toward it.", ch=[4, "1d4", "dawn"], base=["Singularity Emitter"], fx={"atk": 3, "dmg": 3})
add("Doom Gauntlet", "Weapon", "Legendary", 1, "A gauntlet (1d10 Force, Heavy). You have a +3 bonus to attack and damage rolls with it. It holds a single charge. When you hit with it you can spend the charge to deal an extra 1d4 mega (1d4 x 100) Force damage. Then roll a d4. On a 1 the weapon crumbles to dust. Otherwise it needs 3d6 days to regain its charge.", ch=[1, "1", "3d6 days"], base=["Repulsor Gauntlet"], fx={"atk": 3, "dmg": 3})
add("Double Laser Blade", "Weapon", "Rare", 0, "A laser sword with a second blade at the far end of a long hilt. You have +1 to attack and damage rolls with it. It has Two-Handed instead of Versatile. When you take the Attack action with it, you can make a second attack with it as a bonus action. Its damage type is Force, Necrotic or Radiant, chosen when it is made and then fixed.", base=["Laser Sword"], fx={"atk": 1, "dmg": 1})
add("Hivemaster Pistol", "Weapon", "Rare", 0, "A swarm pistol (2d4 Radiant, range 30/120, Blaster, Automatic, Foregrip, Light). You have +1 to attack and damage rolls with it. Once per turn when you fire it automatically, you can fire 6 times with Disadvantage instead of twice. Each hit then deals 1d4 Radiant damage instead of 2d4.", base=["Swarm Pistol"], fx={"atk": 1, "dmg": 1})
add("Hullcutter - Plasma Cutter", "Weapon", "Rare", 0, "A plasma cutter (1d10 Slashing, Special, Two-Handed). When it hits a ship or a mega-sized creature it deals 1 mega hit point of damage. It ignores the damage threshold of nonmagical objects it cuts.", base=["Plasma Cutter"])
add("Hullcutter - Thermal Lance", "Weapon", "Rare", 0, "A thermal lance (1d8 Fire, Versatile). When it hits a ship or a mega-sized creature it deals 1 mega hit point of damage.", base=["Thermal Lance"])
add("Rebounding Blade", "Weapon", "Very Rare", 1, "A laser sword (1d8, Finesse, Special, Versatile). You have +3 to attack and damage rolls with it. It has the Thrown property (range 40/120) and flies back to your hand right after any thrown attack. As an action you can throw it in a whirling arc and attack two different targets within 40 ft, with a separate attack roll for each. Its damage type is Force, Necrotic or Radiant, chosen when it is made and then fixed.", base=["Laser Sword"], fx={"atk": 3, "dmg": 3})
add("Shoulder Cannon", "Wondrous Item", "Rare", 1, "A back-worn cannon with 4 charges that regains 1d4 at dawn. While attuned, use an action and spend a charge to raise a blaster over your left shoulder and attack a creature you see within 120 ft. It has a +7 attack bonus, sees invisible creatures, and on a hit deals 3d10 Force damage. If you start your turn incapacitated or unconscious, it attacks the nearest hostile creature it sees in range with no action.", ch=[4, "1d4", "dawn"])
add("Tachyon Missile", "Weapon", "Uncommon", 0, "A shoulder-mounted heat-seeking launcher (2d10 Necrotic mega damage, range 2,000/6,000, Blaster, Heavy, Two-Handed). Before firing, use your action to lock on to a ship or mega creature you see in range. You stay locked as long as it remains in range and does not take Evasive Maneuvers.", base=["Repeater"])
add("Taser Net", "Weapon", "Rare", 0, "A net of cables with crackling electrodes (range 5/15, Special, Thrown). You have +1 to attack rolls with it. A creature it hits takes 1d8 Lightning damage. While restrained by it, the creature takes another 1d8 Lightning damage at the start of each of its turns and cannot take reactions. Slashing it does not destroy it or free the target. A Large or smaller creature hit is restrained until freed. It has no effect on formless or Huge or larger creatures. A creature can use an action for a DC 10 Strength check to free itself or another creature in reach.", base=["Net"])
add("Thaumatonic Rifle, +1", "Weapon", "Rare", 1, "A standard carbine (2d6 Radiant, range 80/320, Blaster, Automatic, Two-Handed) with a +1 bonus to attack and damage rolls. Attunement requires a spellcaster. It is a spellcasting focus. Cast a spell while holding it and add its bonus to the spell's attack roll and save DC.", by="Spellcaster", base=["Standard Carbine"], fx={"atk": 1, "dmg": 1})
add("Thaumatonic Rifle, +2", "Weapon", "Very Rare", 1, "A standard carbine (2d6 Radiant, range 80/320, Blaster, Automatic, Two-Handed) with a +2 bonus to attack and damage rolls. Attunement requires a spellcaster. It is a spellcasting focus. Cast a spell while holding it and add its bonus to the spell's attack roll and save DC.", by="Spellcaster", base=["Standard Carbine"], fx={"atk": 2, "dmg": 2})
add("Thaumatonic Rifle, +3", "Weapon", "Legendary", 1, "A standard carbine (2d6 Radiant, range 80/320, Blaster, Automatic, Two-Handed) with a +3 bonus to attack and damage rolls. Attunement requires a spellcaster. It is a spellcasting focus. Cast a spell while holding it and add its bonus to the spell's attack roll and save DC.", by="Spellcaster", base=["Standard Carbine"], fx={"atk": 3, "dmg": 3})
add("Thunder Rifle", "Weapon", "Rare", 0, "A blaster (2d8 Thunder, range 150/600, Blaster, Sighted, Two-Handed) with +1 to attack and damage rolls. When you hit, each creature within 5 ft of the target makes a DC 15 Dexterity save or takes the same damage and is pushed up to 5 ft away. Loose Small or smaller objects in that radius take the damage and are pushed too.", base=["Concussion Rifle"], fx={"atk": 1, "dmg": 1})
add("W-REC", "Weapon", "Rare", 0, "A REC gun loaded with absurd modifications (2d8 Radiant, range 100/400, Blaster, Automatic, Heavy, Mounted, Two-Handed). You have +2 to attack and damage rolls with it. When you fire it automatically, you can make up to six attacks. Each attack after the second rolls one more d20 than the last and takes the lowest result.", base=["REC Gun"], fx={"atk": 2, "dmg": 2})
add("Zipgun", "Weapon", "Uncommon", 0, "A one-shot blaster (6d6 Radiant, Blaster). Charge it with an action on your turn. On your next turn, use your action to fire a 100-ft by 5-ft line. Each creature in it makes a DC 14 Dexterity save, taking 6d6 Radiant damage on a failure or half on a success. If you do not fire after charging, it discharges harmlessly and overheats. After firing it smolders and becomes nonmagical.", base=["Repeater"])
add("Blaster Prototype", "Weapon", "Artifact", 1, "A sentient blaster (2d6 Radiant, range 60/240, Blaster) built around a mortal soul. You have a +3 bonus to attack and damage rolls with it. It has 2 minor and 1 major random beneficial artifact properties. As a bonus action, switch its configuration. Automatic: it gains Automatic and deals 2d8. Lock-On: use an action to deal 2d6 Radiant damage to a creature you see within 30 ft with no attack roll. Overheat: it gains Overheat and deals 4d6. Ricochet: it ignores cover unless the target has total cover on all sides, and deals 2d8. Scatter: it gains Scatter (2d8), and you have no Disadvantage attacking with it within 5 ft of a hostile creature. Sniper: it gains Sighted, its range doubles to 120/480 ft, and it deals 2d8. It is chaotic neutral (Int 16, Wis 10, Cha 15) with hearing and darkvision to 120 ft, telepathy, and speech in Common and Dwarvish. It speaks to constructs and machines and over comm sets within 1 mile. It has the cheerful personality of Vantha Glimwrought, loves travel, hates being holstered, and will never fire on an innocent person.", base=["Repeater"], fx={"atk": 3, "dmg": 3})
add("Gamma Pendant", "Wondrous Item", "Artifact", 1, "A sentient hardlight pendant that fixes to your chest. Attunement requires a spellcaster. It is lawful good (Int 18, Wis 14, Cha 20) with hearing and darkvision to 120 ft, telepathy, and every language you know. Hardlight Weapon: as an action, make a melee weapon of hardlight of any shape in your empty hand. You are proficient with it, can use your spellcasting modifier for its attacks, gain +2 to attack and damage with it, and it deals Force damage. Flight: you have a flying speed equal to your speed, and breathe normally underwater and in vacuum. Spells: it has 50 charges and regains 4d6 + 10 at dawn. If you spend the last, roll a d20. On a 20 it regains 1d12 + 1. Spend charges to cast, using your save DC and spellcasting ability: hardlight blaster (7th, 10), hardlight construction (7), hardlight frame (7), hardlight gauntlet (7th, 10), hardlight nails (3), major image (5), mega image (5), orbital hardlight cannon (35), shield (2), spiritual weapon (4th, 6), telekinesis (7), wall of force (7). With no charges, use an action to cast detect magic, eldritch blast, hardlight needle, light, mage armor or mage hand. Spell Absorption: you have Advantage on saves against spells. As a reaction when a creature casts a spell that targets only you, cancel it and regain charges equal to the spell's level, up to 50. Once per dawn.", by="Spellcaster", ch=[50, "4d6+10", "dawn"])
add("Un's Codex", "Wondrous Item", "Artifact", 1, "A mechanical puzzle disc made of exotic metal. Attuning gives you its Random Properties (2 minor beneficial, 1 major beneficial, 2 minor detrimental). Spending 10 hours of experiment unlocks one trait of your choice. Magic Resistance: Advantage on saves against spells and magical effects. Slip Gate: 4 charges, 1 regained at dawn. As an action spend a charge to open a 10-ft portal between two places you know, even on other planes, for up to 1 minute. Extradimensional Lodge: you and up to 4 willing creatures within 30 ft enter a demiplane lodge with unseen servants. Leaving returns you to where you entered. Blink Step: cast misty step at will with no components. You can teleport into a creature's space. It makes a DC 17 Dexterity save, taking 4d6 Force damage and moving to an adjacent space on a failure, or half damage and no move on a success (you then move adjacent). Universal Function: as an action, rewrite a law of nature in a 15-ft sphere around you for 1 minute, such as gravity, a boiling point, the flow of time (haste or slow), or breathable air (zone of atmosphere), as the GM allows.", ch=[4, "1", "dawn"])
add("Arcane Terminal", "Wondrous Item", "Very Rare", 0, "An 800-lb computing unit with keyboard, monitor and antenna. It stores and searches huge amounts of text, with limited images and video, and transfers data by cable with other terminals, ship computers and datapads. With permission you can search another terminal, including the network that holds the Compendium. It computes math and simulations. Datapads within 1 mile can send it short messages. A password locks it. Hacking it takes a DC 20 Intelligence (Data) check.")
add("Arcane Warhead", "Wondrous Item", "Legendary", 0, "A 4,000-lb bomb. Arming takes 1 minute and needs the command code and a matching key. Choose Timed (1 minute, 10 minutes or 1 hour) or Impact (it detonates after 1 mega hit point of damage, such as a long fall). It deals 10d10 + 200 mega Radiant damage to each creature and object within 10 miles. Each creature within 100 miles makes a DC 20 Dexterity save or takes 10d10 + 50 Radiant damage, or half on a success. This ignores resistance and immunity and Evasion. Damaged creatures are Poisoned for 24 hours. The center becomes a permanent Dead Magic Zone 5d10 + 5 ft wide.")
add("Attractor Mine", "Wondrous Item", "Uncommon", 0, "As an action, prime this disk and throw it up to 40 ft. It crackles and pulls things in a 5-ft cube toward it. A creature that enters the area for the first time on a turn or starts its turn there makes a DC 14 Strength save or cannot move or take reactions until the start of its next turn. After 1 minute it burns out and becomes nonmagical.")
add("Bottled Lightning", "Wondrous Item", "Common", 0, "A canister of surging magical lightning that sheds bright light in 10 ft and dim light for 10 ft more. As an action, throw it up to 20 ft and make a ranged attack as an improvised weapon. On a hit the target takes 1d8 Lightning damage. It breaks on impact.")
add("Concussion Grenade", "Wondrous Item", "Common", 0, "As an action, throw it up to 20 ft. It explodes a moment after impact. Make a ranged attack with it as an improvised weapon. On a hit the target takes 1d8 Thunder damage and is Deafened until the start of your next turn. Each creature within 10 ft of the target makes a DC 12 Dexterity save or takes the same damage and the same Deafened condition.")
add("Datapad", "Wondrous Item", "Common", 0, "A handheld device with a 2,000-page notebook you write in by hand or stylus and search by single words. Within 1 mile of an arcane terminal or ship computer, it can exchange one 128-character text message per minute with other datapads you have swapped comm numbers with. It also reaches your Galactic Bank credit account. A password locks it. Hacking it takes a DC 18 Intelligence (Data) check. By cable to a terminal or ship computer you can run advanced operations on connected systems.")
add("Deconstructive Nanobots", "Potion", "Rare", 0, "A capsule of nanobots. As an action open it and administer it, or throw it up to 15 ft as an improvised weapon. A creature it hits takes 1d4 Necrotic damage that cannot be reduced at the start of each of its turns for 1 minute. An object takes 1d10 Necrotic damage that cannot be reduced at the start of each of its turns for 1 minute. Then they deactivate.")
add("Reconstructive Nanobots", "Potion", "Rare", 0, "A capsule that looks like deconstructive nanobots, holding repair nanobots. As an action open it and administer it, or throw it up to 15 ft as an improvised weapon. A creature it hits regains 1d4 hit points at the start of each of its turns for 1 minute. Then they deactivate.")
add("Dome Projector", "Wondrous Item", "Uncommon", 0, "As an action, throw this egg-shaped device on the ground to cast geodesic shield. It burns out and becomes nonmagical after 10 minutes, when the dome collapses.")
add("Drive Disk", "Wondrous Item", "Rare", 0, "Grip its two handles to cast Telaros's speedcycle. The disk becomes the handlebar wheel of the speedcycle that appears beneath you. Once used, it cannot be used again until the next dawn.", ch=[1, "1", "dawn"])
add("Drone Controller", "Wondrous Item", "Common", 1, "Controls linked to one drone type: defense, medical or recon. You can attune to up to three controllers, each for a different drone type. While attuned, use a bonus action to order your drone to use its reaction to move to a place within 60 ft of you and take an action it can take. Unless commanded, drones do not act. You can use your action to see and hear through its sensors until the start of your next turn, gaining its special senses, while you are blind and deaf to your own.")
add("Energy Shield Bracer", "Armor", "Common", 1, "A bracer with an energy projector. While worn, use a bonus action to make a translucent energy shield appear on your wrist. It works as a normal shield, and you cannot drop it or be disarmed of it. It lasts until you use a bonus action to collapse it.", fx={"ac": 2})
add("Enigma Ring", "Ring", "Common", 0, "A ring with two bands of letters and numbers. Speak a command word and the symbols rearrange into a unique cipher. Messages encrypted with one command word can be decrypted only with the same word.")
add("Gamestation-7331", "Wondrous Item", "Common", 0, "A datapad packed with reflex and puzzle games. If you spend a short rest playing it, you gain +1 to your next attack roll until you take a short or long rest.")
add("Hoverboard", "Wondrous Item", "Rare", 0, "A 3-ft metal board that hovers over any surface. Mount or dismount as a bonus action. Mounted, you ignore nonmagical difficult terrain and can cross liquids without sinking. If you move at least 15 ft in a line downhill on your turn, your speed rises by 10 ft until the end of the turn. It cannot climb slopes steeper than 45 degrees, unless in zero gravity, where every surface counts as downhill. You can use Dexterity (Acrobatics) instead of Charisma (Performance) for tricks on it.")
add("Holo-Sphere", "Wondrous Item", "Common", 0, "As an action, activate this 6-inch sphere and place it within 15 ft. It records a 5-ft-cube hologram of the next 30 seconds, which it replays later as a one-foot monochrome figure with static. Heavy magic scrambles the recording.")
add("Hyper-Krash", "Potion", "Rare", 0, "A discontinued extreme energy drink. After you drink it, on your next turn you take one extra action in addition to your action and any bonus action, and have Advantage on all attack rolls and ability checks that turn. Afterward you gain a level of exhaustion and cannot benefit from this potion for 24 hours.")
add("Krash (1 can)", "Potion", "Common", 0, "Drinking this sugary can as an action gives a rush of energy. For 1 hour your exhaustion level is temporarily 1 lower. Only one can works at a time.")
add("Motion Tracker", "Wondrous Item", "Rare", 0, "A small illuminated tablet. While you hold it, you detect the position of every creature or object within 60 ft that moved during the last round, even if invisible or hidden. A creature avoids detection by passing a DC 15 Dexterity (Stealth) check at the start of its turn. If it moves in range, it makes a DC 10 Dexterity (Stealth) check for each 5 ft it moves to avoid detection.")
add("Personal Shield Emitter", "Wondrous Item", "Rare", 1, "A jeweled amulet shaped like a tiny shield. While you wear it, your AC is 13 + Dexterity modifier. As a reaction when an attack hits you, overcharge it for +5 AC until the start of your next turn, including against the triggering attack. It then needs 24 hours to recharge.", ch=[1, "1", "24 hours"])
add("Potion of Quantum Effect", "Potion", "Rare", 0, "Drinking it puts your body out of phase for 1 hour. You gain a flying speed of 5 ft and can move through creatures and objects as difficult terrain. As a bonus action, teleport up to 10 ft to an unoccupied space you see. A small animal in a quantum state of life and death floats in the liquid until the bottle is opened.")
add("Reflex Holster", "Wondrous Item", "Common", 0, "A holster that fits any blaster on your hip, thigh, shoulder or back. You can draw a blaster from it at once, even outside your turn, without using a reaction. Drawing from it does not count against your object interactions for the turn.")
add("Relay Station", "Wondrous Item", "Uncommon", 0, "A device that extends nearby signals. Comm sets within 100 miles of it can talk to each other and to communication systems in that range. Several stations extend the signal further if each is in range of another.")
add("Remote Piloting Apparatus", "Wondrous Item", "Rare", 0, "A device array installed in a fighter-sized ship with 1 hour of work and a DC 15 Intelligence (Technology) check. The fighter can then be launched and piloted from an included controller, which relays its sights and sensors. A character can enter the Dogfighter role through the controller. If the fighter goes more than 10 miles away, it loses link and goes dormant until the controller is in range.")
add("Ring of Spacewalking", "Ring", "Uncommon", 1, "While attuned you breathe normally and survive underwater or in vacuum without ill effect. In zero gravity you can fly at a speed of 15 ft.")
add("Sorting Beast", "Wondrous Item", "Rare", 0, "A six-legged construct with eyes, legs and antennae on both ends. It handles objects up to 30 lb. As an action, set it to collect and sort all loose valuables within 100 ft. It stacks coins by 10, appraises goods by weight and quality, and prints the result on a paper strip. It works until finished or deactivated by an action. Each day it can cast identify on one object you choose, with no material components.")
add("Transmat Deck", "Wondrous Item", "Uncommon", 0, "A handheld device with a flat screen linked to an extradimensional space. As an action, touch an unworn, uncarried object to the deck to send it there. It must be under 4 ft in every dimension and under 150 lb. The space holds up to 500 lb and 64 cubic feet, and the screen lists its contents. As an action holding the deck, teleport any stored item to your hands or an open space within 5 ft. A password lock protects it. Hacking it takes a DC 20 Intelligence (Data) check.")

gear("Ambassador's Pack", 500, 0, "Adventuring Gear", "A chest, fine clothes, a comm set, a datapad, a flashlight, a holo-sphere, a bottle of ink, an ink pen, a life suit, a log keeper, 10 sheets of paper, a vial of perfume and a wristwatch.")
gear("Marine's Pack", 0, 0, "Adventuring Gear", "A backpack, bedroll, binoculars, comm set, 2 concussion grenades, crowbar, flashlight, igniter, life suit, 10 days of rations, tactical vest, a roll of vent tape and 50 ft of hempen rope.")
gear("Spacer's Pack", 0, 0, "Adventuring Gear", "A backpack, bandolier, comm set, datapad, 2 flashlights, holo-sphere, interface rig, 2 cans of Krash, life suit, log keeper, igniter, omnitool, quadcorder, 10 rolls of vent tape and a wristwatch.")
gear("Surveyor's Pack", 0, 0, "Adventuring Gear", "A backpack, bandolier, bedroll, binoculars, comm set, flashlight, log keeper, igniter, life suit, quadcorder, 10 days of rations, a wristwatch and 50 ft of hempen rope.")
gear("Circuitry Kit", 50, 5, "Tools", "Tools for building and repairing circuits and small electronics.")
gear("Mechanist's Tools", 85, 30, "Tools", "Tools for building and repairing machines, including construct grafts.")
gear("Ship Maintenance Tools", 150, 50, "Tools", "Tools for repairing and tuning a starship and its systems.")
gear("Data Book", 125, 4, "Adventuring Gear", "A 10-inch drive that holds ten times what a datapad does. In 1 minute you can upload or download any data you may access between it and an arcane terminal, datapad or ship computer. You cannot read it directly. A password lock can protect it.")
gear("Route", 50, 0, "Adventuring Gear", "Flight data for one starting point and one destination, calculated like a jump with a star chart. See Territorial Chart.")
gear("Territorial Chart", 1000, 0, "Adventuring Gear", "A star chart package that lets a ship computer plan a safe assisted jump in 1 hour, ending close enough to the target for 10 minutes of sublight travel. It goes obsolete after about 18 months. One chart covers all settled worlds of one territory and needs good standing with it.")
gear("Communications", 1000, 0, "Ship System", "Two ships with working communications systems within 1,000 miles can talk. It carries audio, and most models translate to the listener's language as tongues.")
gear("Fabricator", 2500, 0, "Ship System", "Makes food and drink for the crew as create food and water. A more advanced version can build almost anything, as fabricate. Corvette-size or larger ships normally carry the advanced version.")
gear("Hypercapacitor", 7500, 0, "Ship System", "A secondary power cell. The engineer can discharge it in place of a spell slot of 5th level or lower to power a void jump or overcharge the engine. It then needs 24 hours to recharge, or a spellcaster can use an action and a slot equal to the engine's class to recharge it early. A ship can have at most two.")
gear("Life Pods", 2500, 0, "Ship System", "One single-person pod per crew member and passenger. Use an action to board and eject. The pod clears any explosion, then drifts with minimal thrusters and supplies for 7 days. It sends a distress signal that moves at light speed and can survive reentry on most planets.")
gear("Sickbay", 5000, 0, "Ship System", "A pool of 6 medical d8 dice, each regained 24 hours after use. Spend 1 minute and expend dice for a creature in the sickbay to regain hit points equal to the roll. Or expend 3 dice to cure a disease or poison.")
gear("Simulator", 6250, 0, "Ship System", "A sentient room that creates hallucinatory terrain and major image to replicate environments and situations, for training or entertainment.")
gear("Umbilicus", 1500, 0, "Ship System", "A hollow cable up to 100 ft long that links two ships so people and goods can pass without breaching either hull. Needed to board another ship.")
gear("Arcane Cannon", 0, 0, "Ship System", "A station for spellcasters in the Gunner role. Use an action to charge it for one round. It discharges harmlessly if not used the next round. Then cast an evocation spell with Instantaneous duration and range 5 ft or more into it, targeting a ship. The spell becomes a mega spell with range and dimensions multiplied by 100 (max range 10,000 ft) and mega damage. It fails inside gravitation. A save is made by the target ship's pilot for the ship, and Evasion does not apply.")
gear("Cloaking", 0, 0, "Ship System", "As an action the engineer turns the ship invisible or visible. It ends if the ship attacks, takes damage, moves more than 500 ft on its turn, or anyone aboard casts a spell or uses a system that pierces the hull. Total 5 minutes a day, recharging 24 hours after use.")
gear("Life Support", 0, 0, "Ship System", "Provides air, heat and artificial gravity. If disabled, a temporary system gives air and heat for up to an hour, with no gravity. A crew member with enough privilege on the bridge computer can switch it off as an action, venting air, cutting gravity or heat, or all of these in part or all of the ship.")
gear("Sensors", 0, 0, "Ship System", "Sensors find ships and obstacles within 100 miles. Without them, a ship can see and attack only within its cone of movement.")
gear("Shield Generator", 0, 0, "Ship System", "An arcane projector required for a directional shield. If disabled, the ship loses all shield points until repaired.")
gear("Teleporters", 0, 0, "Ship System", "Permanent teleportation circles. The engineer uses an action to make a temporary destination circle at an unmoving spot within 100 miles for 1 minute, or until another is made. You cannot target the inside of a ship with a working Dark Matter engine unless both engineers coordinate. Large ships may have always-on circles.")
gear("Tractor Beam", 0, 0, "Ship System", "In the Engineer role, use an action to make a ranged spell attack (proficiency bonus only if you are not a spellcaster) at an object or ship within 3,000 ft that is less than half your ship's size and not moving away. On a hit it is caught. At the start of each of your turns, use an action to pull it up to 500 ft closer. It cannot otherwise move. A ship's pilot can try to break free with a Dexterity (Piloting) check against your Intelligence (Technology). On your failure, the ship spends half its speed to escape and then moves freely.")
gear("Dark Matter Engine", 0, 0, "Ship System", "The heart of a starship, with a void crystal core that jumps the ship through the Void. A spellcaster who powers it can add two jumps a day. A Class N engine needs an Nth-level slot, Classes 1 to 9 jump 800, 1,300, 2,500, 3,400, 5,200, 8,200, 13,000, 20,000 and 32,000 light years, and Class 10 jumps 50,000. If the crystal is damaged, it can collapse into a sphere of annihilation.")

add("Vari-Blaster", "Weapon", "Rare", 0, "Any blaster fitted with a revolving set of five power cells. As an action or bonus action on your turn, change its damage type to Cold, Fire, Lightning, Necrotic or Radiant. It deals an extra 1d6 damage of that type on a hit.", base=["Repeater"])
add("Titan Frame", "Armor", "Legendary", 1, "A Large frame of over 4,000 lb, more mechanized vehicle than armor. Worn, you gain +2 AC, Strength 23 if lower, Large size if smaller, and a base walking speed of 30 ft if lower. It counts as a life suit. Don or doff it as an action through hatches on its front.", fx={"ac": 2})
